 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = 5
    row_seps = [r for r in range(h) if all(v == sep for v in grid[r])]
    col_seps = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    rbounds = [-1] + row_seps + [h]
    cbounds = [-1] + col_seps + [w]
    row_ranges = [(rbounds[i]+1, rbounds[i+1]) for i in range(len(rbounds)-1)]
    col_ranges = [(cbounds[i]+1, cbounds[i+1]) for i in range(len(cbounds)-1)]
    # Pick the tile carrying the most cells of a non-separator color as the motif.
    best = None
    for ri, (r0,r1) in enumerate(row_ranges):
        for ci, (c0,c1) in enumerate(col_ranges):
            counts = {}
            for r in range(r0,r1):
                for c in range(c0,c1):
                    v=grid[r][c]
                    if v:
                        counts[v]=counts.get(v,0)+1
            for color,n in counts.items():
                if best is None or n > best[0]: best=(n,ri,ci,color)
    _, tri,tci,tcolor=best
    tr0,tr1=row_ranges[tri]; tc0,tc1=col_ranges[tci]
    motif={(r-tr0,c-tc0) for r in range(tr0,tr1) for c in range(tc0,tc1) if grid[r][c]==tcolor}
    out=[[sep if grid[r][c]==sep else 0 for c in range(w)] for r in range(h)]
    for ri,(r0,r1) in enumerate(row_ranges):
        # Color indicated by the 2x2 marker in the first tile of this band.
        vals={grid[r][c] for r in range(r0,r1) for c in range(col_ranges[0][0],col_ranges[0][1]) if grid[r][c] not in (0,sep)}
        color=next(iter(vals))
        for c0,c1 in col_ranges:
            for dr,dc in motif:
                if r0+dr<r1 and c0+dc<c1: out[r0+dr][c0+dc]=color
    return out
